}

Reference answer (for understanding intent only; do not copy whole program unless the whole student solution is only one function/method):
// Node in parameter represents root of tree
public Node delete(Node root, Node delete) {
    Node y = null; //y: node to delete (after swap)
    if (delete.left == null || delete.right == null) {
        y = delete;
    } else {
        y = treeMinimum(delete.right);
    }
    Node x = null; // non-null child of y
    if (y.left != null) {
        x = y.left;
    } else {
        x = y.right;
    }
    // now delete y
    if (x != null) {
        x.parent = y.parent;
    }
    if (y.parent == null) {
        root = x;
    } else {
        if (y == y.parent.left) {
            y.parent.left = x;
        } else {
            y.parent.right = x;
        }
    }
    // Copy data
    if (y != delete) {
        delete.key = y.key;
    }
    // y should have no reference and should be deleted by the java gc
    return root;
}
// Helper function
public Node treeMinimum(Node n) {
    while (n.left != null) {
        n = n.left;
    }
    return n;
}

