// Returns the maximum value that can be put in a knapsack 
    // of capacity W 
    public static double knapSack(double[] val, int[] wt, int W) {

                int n = val.length; 
        int i, w; 
        double K[][] = new double[n + 1][W + 1]; 

        // Build table K[][] in bottom up manner 
        for (i = 0; i<= n; i++) { 
            for (w = 0; w<= W; w++) { 
                if (i == 0 || w == 0) 
                    K[i][w] = 0; 
                else if (wt[i - 1]<= w) 
                    K[i][w] = max(val[i - 1] + K[i - 1][w - wt[i - 1]], K[i - 1][w]); 
                else
                    K[i][w] = K[i - 1][w]; 
            } 
        } 

        return K[n][W]; 
    } 

static double max(double a, double b)  
{ 
    return (a > b) ? a : b;
    }

